using System;
using System.Collections.Generic;
using System.IO;
using System.Linq;
using System.Windows.Forms;

namespace KharvoxLauncher;

// SFS compiled profile is deliberately user-local, not generated by CI.
// Restore only from a known-good prior installation chosen by the user.
// Never generate placeholder SPIR-V, download unknown archives, or overwrite
// the only surviving profile without retaining its original.
internal static class SfsProfileRecovery
{
    internal static bool ChooseAndRestore(IWin32Window owner)
    {
        using var picker = new FolderBrowserDialog
        {
            Description = "Choose sfs-profile from an earlier WORKING KHARVOX installation (or choose the installation folder).",
            ShowNewFolderButton = false
        };
        if (picker.ShowDialog(owner) != DialogResult.OK) return false;
        var selected = picker.SelectedPath;
        var source = Path.GetFileName(selected)
            .Equals("sfs-profile", StringComparison.OrdinalIgnoreCase)
            ? selected : Path.Combine(selected, "sfs-profile");
        var target = Path.Combine(AppContext.BaseDirectory, "sfs-profile");
        try
        {
            if (!VulkanSfs.HasCompleteShaderProfile(sourceIsProfileDirectory: source))
            {
                MessageBox.Show(owner, "Selected folder does not contain 75 valid SFS shader files:"
                    + Environment.NewLine + source
                    + Environment.NewLine + Environment.NewLine
                    + "No files have been copied.",
                    "KHARVOX — Invalid SFS profile",
                    MessageBoxButtons.OK, MessageBoxIcon.Warning);
                return false;
            }
            if (Path.GetFullPath(source).TrimEnd(Path.DirectorySeparatorChar)
                .Equals(Path.GetFullPath(target).TrimEnd(Path.DirectorySeparatorChar),
                    StringComparison.OrdinalIgnoreCase))
                return true;

            var confirm = MessageBox.Show(owner,
                "Restore this verified 75-file SFS shader profile?"
                + Environment.NewLine + Environment.NewLine
                + "From: " + source
                + Environment.NewLine + "Into: " + target
                + Environment.NewLine + Environment.NewLine
                + "Existing shader files will be moved into a separate backup folder."
                + Environment.NewLine + "The original working installation will not be changed.",
                "KHARVOX — Restore SFS profile", MessageBoxButtons.YesNo,
                MessageBoxIcon.Question);
            if (confirm != DialogResult.Yes) return false;
            Restore(source, target);
            MessageBox.Show(owner, "75 verified SFS shader files restored."
                + Environment.NewLine + "You can now try the SFS renderer.",
                "KHARVOX — SFS recovered", MessageBoxButtons.OK,
                MessageBoxIcon.Information);
            return true;
        }
        catch (Exception ex) when (ex is IOException or UnauthorizedAccessException
            or ArgumentException or InvalidOperationException)
        {
            MessageBox.Show(owner, "Shader recovery failed safely: " + ex.Message
                + Environment.NewLine + "The original source folder was not changed.",
                "KHARVOX — SFS recovery", MessageBoxButtons.OK,
                MessageBoxIcon.Warning);
            return false;
        }
    }

    internal static void Restore(string source, string target)
    {
        if (!VulkanSfs.HasCompleteShaderProfile(sourceIsProfileDirectory: source))
            throw new InvalidDataException("Source does not contain a complete valid SFS profile.");

        var destinationParent = Path.GetDirectoryName(Path.GetFullPath(target))
            ?? throw new InvalidDataException("Invalid destination path.");
        Directory.CreateDirectory(destinationParent);
        var staging = Path.Combine(destinationParent,
            ".sfs-profile-staging-" + Guid.NewGuid().ToString("N"));
        var backup = Path.Combine(destinationParent,
            "sfs-profile-backup-" + DateTime.UtcNow.ToString("yyyyMMdd-HHmmss")
            + "-" + Guid.NewGuid().ToString("N").Substring(0, 6));
        var backedUp = false;
        var installed = false;
        try
        {
            Directory.CreateDirectory(staging);
            foreach (var file in Directory.EnumerateFiles(source, "*.spv",
                SearchOption.TopDirectoryOnly))
            {
                if ((File.GetAttributes(file) & FileAttributes.ReparsePoint) != 0)
                    throw new InvalidDataException("Linked shader files cannot be restored.");
                File.Copy(file, Path.Combine(staging, Path.GetFileName(file)));
            }
            if (!VulkanSfs.HasCompleteShaderProfile(sourceIsProfileDirectory: staging))
                throw new InvalidDataException("Staged shader profile failed verification.");
            if (Directory.Exists(target))
            {
                Directory.Move(target, backup);
                backedUp = true;
            }
            Directory.Move(staging, target);
            installed = true;
        }
        catch
        {
            if (backedUp && !Directory.Exists(target) && Directory.Exists(backup))
                Directory.Move(backup, target);
            throw;
        }
        finally
        {
            if (Directory.Exists(staging))
                try { Directory.Delete(staging, true); } catch { }
            // Existing target remains preserved under backup after success.
            // Never remove the backup or the user's source.
        }
    }

    internal static bool RunSelfTest()
    {
        var root = Path.Combine(Path.GetTempPath(),
            "KHARVOX-SFS-Recovery-" + Guid.NewGuid().ToString("N"));
        try
        {
            var source = Path.Combine(root, "known", "sfs-profile");
            var destination = Path.Combine(root, "new", "sfs-profile");
            Directory.CreateDirectory(source);
            Directory.CreateDirectory(destination);
            File.WriteAllText(Path.Combine(destination, "old-note.txt"), "keep");
            // Synthetic SPIR-V header for transfer integrity test only;
            // never use this data to launch or install into an actual game.
            var bytes = new byte[20];
            BitConverter.GetBytes(0x07230203u).CopyTo(bytes, 0);
            for (var i = 0; i < 75; i++)
                File.WriteAllBytes(Path.Combine(source,
                    i.ToString("x16") + "_VS.vert.spv"), bytes);
            Restore(source, destination);
            return VulkanSfs.HasCompleteShaderProfile(sourceIsProfileDirectory: destination)
                && Directory.GetDirectories(Path.Combine(root, "new"),
                    "sfs-profile-backup-*").Any(path =>
                        File.Exists(Path.Combine(path, "old-note.txt")))
                && Directory.GetFiles(source, "*.spv").Length == 75;
        }
        finally { try { Directory.Delete(root, true); } catch { } }
    }
}
